scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "4000");
    WebSquare.wUnit.addCommand("assert", "log", "selectBox.getSelectedIndex :0");
    WebSquare.wUnit.addCommand("assert", "log1", "end...setCellData..getSelectedIndex :0");
    WebSquare.wUnit.addCommand("assert", "log2", "selectBox.getSelectedIndex :0");
    WebSquare.wUnit.addCommand("assert", "log3", "end...setCellData..getSelectedIndex :0");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

